from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import Json
from typing import Annotated, List
import pytest

app = FastAPI()

@app.post("/upload")
def upload(
    tags: Annotated[Json[List[str]], Form()]
):
    return {"tags": tags}

client = TestClient(app)

def test_json_list_form():
    # Client sends a JSON string in a form field
    # This is the case that was failing
    response = client.post(
        "/upload",
        data={"tags": '["abc", "def"]'}
    )
    assert response.status_code == 200
    assert response.json() == {"tags": ["abc", "def"]}

def test_json_list_form_multiple_values():
    # Ensure that if multiple values are sent for the same key, 
    # it still behaves as expected (usually taking the last one for a single field)
    response = client.post(
        "/upload",
        data={"tags": '["abc", "def"]', "tags": '["ghi", "jkl"]'}
    )
    assert response.status_code == 200
    assert response.json() == {"tags": ["ghi", "jkl"]}

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])
